   139→    @ApiOperation(value = "Create Or Update Edge (saveEdge)",
   140→            notes = "Create or update the Edge. When creating edge, platform generates Edge Id as " + UUID_WIKI_LINK +
   141→                    "The newly created edge id will be present in the response. " +
   142→                    "Specify existing Edge id to update the edge. " +
   143→                    "Referencing non-existing Edge Id will cause 'Not Found' error." +
   144→                    "\n\nEdge name is unique in the scope of tenant. Use unique identifiers like MAC or IMEI for the edge names and non-unique 'label' field for user-friendly visualization purposes." +
   145→                    "Remove 'id', 'tenantId' and optionally 'customerId' from the request body example (below) to create new Edge entity. " +
   146→                    TENANT_AUTHORITY_PARAGRAPH)
   147→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   148→    @PostMapping(value = "/edge")
   149→    public Edge saveEdge(@Parameter(description = "A JSON value representing the edge.", required = true)
   150→                         @RequestBody Edge edge) throws Exception {
   151→        TenantId tenantId = getTenantId();
   152→        edge.setTenantId(tenantId);
   153→        boolean created = edge.getId() == null;
   154→
   155→        RuleChain edgeTemplateRootRuleChain = null;
   156→        if (created) {
   157→            edgeTemplateRootRuleChain = ruleChainService.getEdgeTemplateRootRuleChain(tenantId);
   158→            if (edgeTemplateRootRuleChain == null) {
   159→                throw new DataValidationException("Root edge rule chain is not available!");
   160→            }
   161→        }
   162→
   163→        Operation operation = created ? Operation.CREATE : Operation.WRITE;
   164→
   165→        accessControlService.checkPermission(getCurrentUser(), Resource.EDGE, operation, edge.getId(), edge);
   166→
   167→        return tbEdgeService.save(edge, edgeTemplateRootRuleChain, getCurrentUser());
   168→    }
