   202→    @ApiOperation(value = "Assign edge to customer (assignEdgeToCustomer)",
   203→            notes = "Creates assignment of the edge to customer. Customer will be able to query edge afterwards." + TENANT_AUTHORITY_PARAGRAPH)
   204→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
