   227→        Edge edge = checkEdgeId(edgeId, Operation.UNASSIGN_FROM_CUSTOMER);
   228→        if (edge.getCustomerId() == null || edge.getCustomerId().getId().equals(ModelConstants.NULL_UUID)) {
   229→            throw new IncorrectParameterException("Edge isn't assigned to any customer!");
   230→        }
