   360→            @RequestParam(required = false) String sortOrder) throws ThingsboardException {
   361→        checkParameter("customerId", strCustomerId);
   362→        SecurityUser user = getCurrentUser();
   363→        TenantId tenantId = user.getTenantId();
   364→        CustomerId customerId = new CustomerId(toUUID(strCustomerId));
   365→        checkCustomerId(customerId, Operation.READ);
   366→        PageLink pageLink = createPageLink(pageSize, page, textSearch, sortProperty, sortOrder);
