   392→            @Parameter(description = SORT_PROPERTY_DESCRIPTION, schema = @Schema(allowableValues = {"createdTime", "name", "type", "label", "customerTitle"}))
   393→            @RequestParam(required = false) String sortProperty,
   394→            @Parameter(description = SORT_ORDER_DESCRIPTION, schema = @Schema(allowableValues = {"ASC", "DESC"}))
   395→            @RequestParam(required = false) String sortOrder) throws ThingsboardException {
   396→        checkParameter("customerId", strCustomerId);
   397→        SecurityUser user = getCurrentUser();
   398→        TenantId tenantId = user.getTenantId();
   399→        CustomerId customerId = new CustomerId(toUUID(strCustomerId));
   400→        checkCustomerId(customerId, Operation.READ);
   401→        PageLink pageLink = createPageLink(pageSize, page, textSearch, sortProperty, sortOrder);
   402→        PageData<EdgeInfo> result;
   403→        if (type != null && !type.trim().isEmpty()) {
   404→            result = edgeService.findEdgeInfosByTenantIdAndCustomerIdAndType(tenantId, customerId, type, pageLink);
   405→        } else {
   406→            result = edgeService.findEdgeInfosByTenantIdAndCustomerId(tenantId, customerId, pageLink);
   407→        }
   408→        return checkNotNull(result);
   409→    }
   410→
   411→    @Hidden
   412→    @PreAuthorize("hasAnyAuthority('TENANT_ADMIN', 'CUSTOMER_USER')")
   413→    @GetMapping(value = "/edges", params = {"edgeIds"})
   414→    public List<Edge> getEdgesByIds(
   415→            @RequestParam("edgeIds") String[] strEdgeIds) throws ThingsboardException, ExecutionException, InterruptedException {
   416→        checkArrayParameter("edgeIds", strEdgeIds);
   417→        SecurityUser user = getCurrentUser();
   418→        TenantId tenantId = user.getTenantId();
   419→        CustomerId customerId = user.getCustomerId();
   420→        List<EdgeId> edgeIds = new ArrayList<>();
   421→        for (String strEdgeId : strEdgeIds) {
   422→            edgeIds.add(new EdgeId(toUUID(strEdgeId)));
   423→        }
   424→        ListenableFuture<List<Edge>> edgesFuture;
   425→        if (customerId == null || customerId.isNullUid()) {
   426→            edgesFuture = edgeService.findEdgesByTenantIdAndIdsAsync(tenantId, edgeIds);
   427→        } else {
   428→            edgesFuture = edgeService.findEdgesByTenantIdCustomerIdAndIdsAsync(tenantId, customerId, edgeIds);
   429→        }
   430→        List<Edge> edges = edgesFuture.get();
   431→        return checkNotNull(edges);
   432→    }
   433→
   434→    @ApiOperation(value = "Get Edges By Ids (getEdgeList)",
   435→            notes = "Requested edges must be owned by tenant or assigned to customer which user is performing the request." + TENANT_OR_CUSTOMER_AUTHORITY_PARAGRAPH)
   436→    @PreAuthorize("hasAnyAuthority('TENANT_ADMIN', 'CUSTOMER_USER')")
   437→    @GetMapping(value = "/edges/list")
   438→    public List<Edge> getEdgeList(
   439→            @Parameter(description = "A list of edges ids, separated by comma ','", array = @ArraySchema(schema = @Schema(type = "string")), required = true)
   440→            @RequestParam("edgeIds") String[] strEdgeIds) throws ThingsboardException, ExecutionException, InterruptedException {
   441→        return getEdgesByIds(strEdgeIds);
   442→    }
   443→
   444→    @ApiOperation(value = "Find related edges (findEdgesByQuery)",
   445→            notes = "Returns all edges that are related to the specific entity. " +
   446→                    "The entity id, relation type, edge types, depth of the search, and other query parameters defined using complex 'EdgeSearchQuery' object. " +
   447→                    "See 'Model' tab of the Parameters for more info." + TENANT_OR_CUSTOMER_AUTHORITY_PARAGRAPH)
   448→    @PreAuthorize("hasAnyAuthority('TENANT_ADMIN', 'CUSTOMER_USER')")
   449→    @PostMapping(value = "/edges")
   450→    public List<Edge> findEdgesByQuery(@RequestBody EdgeSearchQuery query) throws ThingsboardException, ExecutionException, InterruptedException {
   451→        checkNotNull(query);
   452→        checkNotNull(query.getParameters());
   453→        checkNotNull(query.getEdgeTypes());
   454→        checkEntityId(query.getParameters().getEntityId(), Operation.READ);
   455→        SecurityUser user = getCurrentUser();
   456→        TenantId tenantId = user.getTenantId();
   457→        List<Edge> edges = checkNotNull(edgeService.findEdgesByQuery(tenantId, query).get());
   458→        edges = edges.stream().filter(edge -> {
   459→            try {
   460→                accessControlService.checkPermission(user, Resource.EDGE, Operation.READ, edge.getId(), edge);
   461→                return true;
   462→            } catch (ThingsboardException e) {
   463→                return false;
   464→            }
   465→        }).collect(Collectors.toList());
   466→        return edges;
   467→    }
   468→
   469→    @ApiOperation(value = "Get Edge Types (getEdgeTypes)",
   470→            notes = "Returns a set of unique edge types based on edges that are either owned by the tenant or assigned to the customer which user is performing the request."
   471→                    + TENANT_OR_CUSTOMER_AUTHORITY_PARAGRAPH)
   472→    @PreAuthorize("hasAnyAuthority('TENANT_ADMIN', 'CUSTOMER_USER')")
   473→    @GetMapping(value = "/edge/types")
   474→    public List<EntitySubtype> getEdgeTypes() throws ThingsboardException, ExecutionException, InterruptedException {
   475→        SecurityUser user = getCurrentUser();
   476→        TenantId tenantId = user.getTenantId();
   477→        ListenableFuture<List<EntitySubtype>> edgeTypes = edgeService.findEdgeTypesByTenantId(tenantId);
   478→        return checkNotNull(edgeTypes.get());
   479→    }
   480→
   481→    @ApiOperation(value = "Sync edge (syncEdge)",
   482→            notes = "Starts synchronization process between edge and cloud. \n" +
   483→                    "All entities that are assigned to particular edge are going to be send to remote edge service." + TENANT_AUTHORITY_PARAGRAPH)
   484→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   485→    @PostMapping(value = "/edge/sync/{edgeId}")
   486→    public DeferredResult<ResponseEntity> syncEdge(@Parameter(description = EDGE_ID_PARAM_DESCRIPTION, required = true)
   487→                                                   @PathVariable("edgeId") String strEdgeId) throws ThingsboardException {
   488→        checkParameter("edgeId", strEdgeId);
   489→        final DeferredResult<ResponseEntity> response = new DeferredResult<>();
   490→        if (isEdgesEnabled() && edgeRpcServiceOpt.isPresent()) {
   491→            EdgeId edgeId = new EdgeId(toUUID(strEdgeId));
   492→            edgeId = checkNotNull(edgeId);
   493→            SecurityUser user = getCurrentUser();
   494→            TenantId tenantId = user.getTenantId();
   495→            edgeRpcServiceOpt.get().processSyncRequest(tenantId, edgeId, fromEdgeSyncResponse -> reply(response, fromEdgeSyncResponse));
   496→        } else {
   497→            throw new ThingsboardException("Edges support disabled", ThingsboardErrorCode.GENERAL);
   498→        }
   499→        return response;
   500→    }
   501→
   502→    private void reply(DeferredResult<ResponseEntity> response, FromEdgeSyncResponse fromEdgeSyncResponse) {
   503→        if (fromEdgeSyncResponse.isSuccess()) {
   504→            response.setResult(new ResponseEntity<>(HttpStatus.OK));
   505→        } else {
   506→            response.setErrorResult(new ThingsboardException(fromEdgeSyncResponse.getError(), ThingsboardErrorCode.GENERAL));
   507→        }
   508→    }
   509→
   510→    @ApiOperation(value = "Find missing rule chains (findMissingToRelatedRuleChains)",
   511→            notes = "Returns list of rule chains ids that are not assigned to particular edge, but these rule chains are present in the already assigned rule chains to edge." + TENANT_AUTHORITY_PARAGRAPH)
   512→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   513→    @GetMapping(value = "/edge/missingToRelatedRuleChains/{edgeId}")
   514→    public String findMissingToRelatedRuleChains(@Parameter(description = EDGE_ID_PARAM_DESCRIPTION, required = true)
   515→                                                 @PathVariable("edgeId") String strEdgeId) throws ThingsboardException {
   516→        EdgeId edgeId = new EdgeId(toUUID(strEdgeId));
   517→        edgeId = checkNotNull(edgeId);
   518→        SecurityUser user = getCurrentUser();
   519→        TenantId tenantId = user.getTenantId();
   520→        return edgeService.findMissingToRelatedRuleChains(tenantId, edgeId, TbRuleChainInputNode.class.getName());
   521→    }
   522→
   523→    @ApiOperation(value = "Import the bulk of edges (processEdgesBulkImport)",
   524→            notes = "There's an ability to import the bulk of edges using the only .csv file." + TENANT_AUTHORITY_PARAGRAPH)
   525→    @PreAuthorize("hasAnyAuthority('TENANT_ADMIN')")
   526→    @PostMapping("/edge/bulk_import")
   527→    public BulkImportResult<Edge> processEdgesBulkImport(@RequestBody BulkImportRequest request) throws Exception {
   528→        SecurityUser user = getCurrentUser();
   529→        RuleChain edgeTemplateRootRuleChain = ruleChainService.getEdgeTemplateRootRuleChain(user.getTenantId());
   530→        if (edgeTemplateRootRuleChain == null) {
   531→            throw new DataValidationException("Root edge rule chain is not available!");
   532→        }
   533→
   534→        return edgeBulkImportService.processBulkImport(request, user);
   535→    }
   536→
   537→    @ApiOperation(value = "Get Edge Install Instructions (getEdgeInstallInstructions)",
   538→            notes = "Get an install instructions for provided edge id." + TENANT_AUTHORITY_PARAGRAPH)
   539→    @PreAuthorize("hasAnyAuthority('TENANT_ADMIN')")
   540→    @GetMapping(value = "/edge/instructions/install/{edgeId}/{method}")
   541→    public EdgeInstructions getEdgeInstallInstructions(
   542→            @Parameter(description = EDGE_ID_PARAM_DESCRIPTION, required = true)
   543→            @PathVariable("edgeId") String strEdgeId,
   544→            @Parameter(description = "Installation method ('docker', 'ubuntu' or 'centos')", schema = @Schema(allowableValues = {"docker", "ubuntu", "centos"}))
   545→            @PathVariable("method") String installationMethod,
   546→            HttpServletRequest request) throws ThingsboardException {
   547→        if (isEdgesEnabled() && edgeInstallServiceOpt.isPresent()) {
   548→            EdgeId edgeId = new EdgeId(toUUID(strEdgeId));
   549→            edgeId = checkNotNull(edgeId);
   550→            Edge edge = checkEdgeId(edgeId, Operation.READ);
   551→            return checkNotNull(edgeInstallServiceOpt.get().getInstallInstructions(edge, installationMethod, request));
   552→        } else {
   553→            throw new ThingsboardException("Edges support disabled", ThingsboardErrorCode.GENERAL);
   554→        }
   555→    }
   556→
   557→    @ApiOperation(value = "Get Edge Upgrade Instructions (getEdgeUpgradeInstructions)",
   558→            notes = "Get an upgrade instructions for provided edge version." + TENANT_AUTHORITY_PARAGRAPH)
   559→    @PreAuthorize("hasAnyAuthority('TENANT_ADMIN')")
   560→    @GetMapping(value = "/edge/instructions/upgrade/{edgeVersion}/{method}")
   561→    public EdgeInstructions getEdgeUpgradeInstructions(
   562→            @Parameter(description = "Edge version", required = true)
   563→            @PathVariable("edgeVersion") String edgeVersion,
   564→            @Parameter(description = "Upgrade method ('docker', 'ubuntu' or 'centos')", schema = @Schema(allowableValues = {"docker", "ubuntu", "centos"}))
   565→            @PathVariable("method") String method) throws Exception {
   566→        if (isEdgesEnabled() && edgeUpgradeServiceOpt.isPresent()) {
   567→            return checkNotNull(edgeUpgradeServiceOpt.get().getUpgradeInstructions(edgeVersion, method));
   568→        } else {
   569→            throw new ThingsboardException("Edges support disabled", ThingsboardErrorCode.GENERAL);
