   574→            notes = "Returns 'true' if upgrade available for connected edge, 'false' - otherwise.")
   575→    @PreAuthorize("hasAnyAuthority('TENANT_ADMIN')")
   576→    @GetMapping(value = "/edge/{edgeId}/upgrade/available")
